function BikeColors.apply(model: Instance)
	for _, part in ipairs(model:GetDescendants()) do
		if part:IsA("MeshPart") then
			local bike, _group, mat = string.match(part.Name, "^(%w+)_(%w+)_(%a+)%d*$")
			local t = bike and BikeColors[bike] and BikeColors[bike][mat]
			if t then
				part.Color = t.color
				part.Material = t.material
				part.Reflectance = t.reflectance
			end
		end
	end
end

